-- Paket ABT "abt-teks-pihak-1nov" (1 Nov 2026): teks para pihak disalin apa adanya, kesimpulan utuh di putusan. Hanya derry_briantono.
-- PRASYARAT "A|B|C|D|E|F|G|H|I": A = variabel 9255/9256/11313 persis LAMA (3 pasang pertama) | B = persis BARU (3 pasang ulang) | C = variabel baru persis (0 / 10) | D = nomor 12100-12119 berisi lain dari paket (0) | E = isian_rtf_penanda persis LAMA (1 / 0) | F = isian_rtf_penanda persis BARU (0 / 1) | G = fungsi baru persis (0 / 2) | H = fungsi bernama sama tetapi isi lain (0) | I = fungsi yang dipakai ada: isian_rtf_kalimat, isian_rtf_blok, isian_bukti_baris, isian_bukti_sumber (4)
SELECT CONCAT_WS('|',
 (SELECT COUNT(*) FROM abt_variabel v WHERE (v.no_var = 9255 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))) = 'f3bceededbca9226d822a58c624941bb') OR (v.no_var = 9256 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))) = 'e80157a53d48defd5742b2d9c920e944') OR (v.no_var = 11313 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))) = '5920df38e05738ab303627d102cdbb69')),
 (SELECT COUNT(*) FROM abt_variabel v WHERE (v.no_var = 9255 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))) = '02f36cc0e7cfcf1500367e2f67e4eaef') OR (v.no_var = 9256 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))) = '69b2a5024676ca4e3a8c57546e9ebd55') OR (v.no_var = 11313 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))) = '5a691cfa2b63d552c9ab1c39cff09f49')),
 (SELECT COUNT(*) FROM abt_variabel v JOIN (SELECT 12100 AS n, '4af79a784ec1b8721c67601eb5e42dcf' AS h UNION ALL SELECT 12101 AS n, '6fa967a7bed44121ea172fcec566e069' AS h UNION ALL SELECT 12102 AS n, 'ac0c1ecb33fb70918013a33d1e723b2f' AS h UNION ALL SELECT 12103 AS n, '949f1f08375cb71670e4dd432486c015' AS h UNION ALL SELECT 12104 AS n, '62849cc880a92605643dce9a22cb5735' AS h UNION ALL SELECT 12105 AS n, '20b1803fd6a356ca73f868d26c314b9b' AS h UNION ALL SELECT 12106 AS n, 'b248a3869dedabbb193d5c7011e4ba44' AS h UNION ALL SELECT 12107 AS n, '0d274bc4b18afac3e557e0f0b3e5716b' AS h UNION ALL SELECT 12108 AS n, '5eea76cfef4f9ecfb0048942ed228932' AS h UNION ALL SELECT 12109 AS n, '40d5644bfdd7fa68b22a21528f7d4a21' AS h) p ON p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, '')))),
 (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var BETWEEN 12100 AND 12119 AND NOT EXISTS (SELECT 1 FROM (SELECT 12100 AS n, '4af79a784ec1b8721c67601eb5e42dcf' AS h UNION ALL SELECT 12101 AS n, '6fa967a7bed44121ea172fcec566e069' AS h UNION ALL SELECT 12102 AS n, 'ac0c1ecb33fb70918013a33d1e723b2f' AS h UNION ALL SELECT 12103 AS n, '949f1f08375cb71670e4dd432486c015' AS h UNION ALL SELECT 12104 AS n, '62849cc880a92605643dce9a22cb5735' AS h UNION ALL SELECT 12105 AS n, '20b1803fd6a356ca73f868d26c314b9b' AS h UNION ALL SELECT 12106 AS n, 'b248a3869dedabbb193d5c7011e4ba44' AS h UNION ALL SELECT 12107 AS n, '0d274bc4b18afac3e557e0f0b3e5716b' AS h UNION ALL SELECT 12108 AS n, '5eea76cfef4f9ecfb0048942ed228932' AS h UNION ALL SELECT 12109 AS n, '40d5644bfdd7fa68b22a21528f7d4a21' AS h) p WHERE p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))))),
 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND routine_name = 'isian_rtf_penanda' AND MD5(routine_definition) = '45baa9b3cac475be6dc2d58d86f63ec5'),
 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND routine_name = 'isian_rtf_penanda' AND MD5(routine_definition) = '1023049d03285626f41df2166e2dbd58'),
 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND ((routine_name = 'isian_awal_kecil' AND MD5(routine_definition) = 'c52e782cd2f205f687896a30ce0c43ca') OR (routine_name = 'isian_rtf_kalimat_kecil' AND MD5(routine_definition) = '4b49fe27b4fa222b9901932221adacd3'))),
 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND routine_name IN ('isian_awal_kecil', 'isian_rtf_kalimat_kecil') AND NOT ((routine_name = 'isian_awal_kecil' AND MD5(routine_definition) = 'c52e782cd2f205f687896a30ce0c43ca') OR (routine_name = 'isian_rtf_kalimat_kecil' AND MD5(routine_definition) = '4b49fe27b4fa222b9901932221adacd3'))),
 (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND routine_name IN ('isian_rtf_kalimat', 'isian_rtf_blok', 'isian_bukti_baris', 'isian_bukti_sumber'))) AS p;
